<script>
// ─── COIN DATA (100 rows) ───
const COIN_COLORS = [
  '#F7931A','#627EEA','#26A17B','#346AA9','#F3BA2F',
  '#9945FF','#E84142','#0033AD','#FF0420','#14F195',
  '#1652F0','#2775CA','#8247E5','#00FFA3','#F0B90B',
  '#2354E6','#E6007A','#00D1FF','#FF6B35','#C3A634',
  '#7B2FBE','#FF4081','#00BCD4','#4CAF50','#FF9800',
  '#9C27B0','#3F51B5','#009688','#795548','#607D8B',
];

function getCoinColor(i) { return COIN_COLORS[i % COIN_COLORS.length]; }

function sparkData(trend) {
  // trend: 'up','down','flat','volatile'
  const base = 50;
  const pts = [];
  for (let i = 0; i < 7; i++) {
    if (trend === 'up') pts.push(base + i * 4 + (Math.random() * 6 - 3));
    else if (trend === 'down') pts.push(base + 24 - i * 4 + (Math.random() * 6 - 3));
    else if (trend === 'flat') pts.push(base + (Math.random() * 4 - 2));
    else pts.push(base + (Math.random() * 24 - 12));
  }
  return pts;
}

function makeSVG(pts, color) {
  const W = 90, H = 32;
  const min = Math.min(...pts), max = Math.max(...pts);
  const range = max - min || 1;
  const xs = pts.map((_, i) => (i / (pts.length - 1)) * W);
  const ys = pts.map(v => H - ((v - min) / range) * (H - 4) - 2);
  const d = xs.map((x, i) => `${i === 0 ? 'M' : 'L'}${x.toFixed(1)},${ys[i].toFixed(1)}`).join(' ');
  const fill = xs.map((x, i) => `${i === 0 ? 'M' : 'L'}${x.toFixed(1)},${ys[i].toFixed(1)}`).join(' ')
    + ` L${W},${H} L0,${H} Z`;
  return `<svg class="spark" viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg">
    <defs><linearGradient id="sg${color.slice(1)}" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="${color}" stop-opacity="0.2"/>
      <stop offset="100%" stop-color="${color}" stop-opacity="0"/>
    </linearGradient></defs>
    <path d="${fill}" fill="url(#sg${color.slice(1)})"/>
    <path d="${d}" stroke="${color}" stroke-width="1.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/>
  </svg>`;
}

function fmt(n, decimals = 2) {
  if (n >= 1e12) return '$' + (n/1e12).toFixed(2) + 'T';
  if (n >= 1e9) return '$' + (n/1e9).toFixed(2) + 'B';
  if (n >= 1e6) return '$' + (n/1e6).toFixed(2) + 'M';
  return '$' + n.toLocaleString('en-US', {minimumFractionDigits: decimals, maximumFractionDigits: decimals});
}

function fmtSupply(n, sym) {
  if (n >= 1e12) return (n/1e12).toFixed(2) + 'T ' + sym;
  if (n >= 1e9) return (n/1e9).toFixed(2) + 'B ' + sym;
  if (n >= 1e6) return (n/1e6).toFixed(2) + 'M ' + sym;
  return n.toLocaleString('en-US') + ' ' + sym;
}

function pctClass(v) {
  if (v > 0) return 'pct up';
  if (v < 0) return 'pct down';
  return 'pct flat';
}

function pctStr(v) {
  return (v > 0 ? '+' : '') + v.toFixed(2) + '%';
}

