let currentCategory = 'top';
let currentNetwork = 'all';
let currentPage = 1;

function getFilteredCoins() {
  let coins = [...ALL_COINS];

  if (currentNetwork !== 'all') {
    coins = coins.filter(c => c[12] === currentNetwork || c[12] === 'all');
  }

  if (currentCategory === 'trending') {
    coins = [...coins].sort((a,b) => Math.abs(b[4]) - Math.abs(a[4]));
  } else if (currentCategory === 'new') {
    coins = coins.slice(60);
  } else if (currentCategory === 'visited') {
    coins = coins.filter((_, i) => i % 3 === 0);
  } else if (currentCategory === 'prediction') {
    coins = coins.filter(c => ['ETH','BTC','SOL','LINK','XRP'].includes(c[2]));
  } else if (currentCategory === 'watchlist') {
    coins = coins.filter(c => [1,2,7,5,4,13].includes(c[0]));
  }

  return coins;
}

function renderTable() {
  const coins = getFilteredCoins();
  const start = (currentPage - 1) * 100;
  const slice = coins.slice(start, start + 100);
  const tbody = document.getElementById('table-body');

  tbody.innerHTML = slice.map((c, i) => {
    const [rank, name, sym, price, h1, h24, h7, mcap, vol, supply, supSym, trend, network] = c;
    const color = getCoinColor(rank - 1);
    const initial = name.charAt(0);
    const pts = sparkData(trend);
    const sparkColor = h7 >= 0 ? '#16c784' : '#ea3943';

    let priceStr;
    if (price >= 1000) priceStr = '$' + price.toLocaleString('en-US', {minimumFractionDigits:2,maximumFractionDigits:2});
    else if (price >= 1) priceStr = '$' + price.toFixed(2);
    else if (price >= 0.01) priceStr = '$' + price.toFixed(4);
    else priceStr = '$' + price.toFixed(8);

    return `<tr data-rank="${rank}">
      <td>
        <span class="star-btn" onclick="toggleStar(this)">☆</span>
        <span class="rank-num">${rank}</span>
      </td>
      <td class="name-col">
        <div class="coin-name-cell">
          <div class="coin-icon" style="background:${color}20;color:${color}">${initial}</div>
          <div class="coin-name-group">
            <span class="coin-name">${name}</span>
            <span class="coin-symbol">${sym}</span>
          </div>
        </div>
      </td>
      <td><span class="price-val">${priceStr}</span></td>
      <td class="col-1h"><span class="${pctClass(h1)}">${pctStr(h1)}</span></td>
      <td><span class="${pctClass(h24)}">${pctStr(h24)}</span></td>
      <td class="col-7d"><span class="${pctClass(h7)}">${pctStr(h7)}</span></td>
      <td class="mcap-val">${fmt(mcap)}</td>
      <td class="vol-val">${fmt(vol)}</td>
      <td class="col-supply supply-val">${fmtSupply(supply, supSym)}</td>
      <td class="col-sparkline sparkline-cell">${makeSVG(pts, sparkColor)}</td>
    </tr>`;
  }).join('');

  // Update counts
  const total = coins.length;
  document.querySelectorAll('.pagination-info, .table-info').forEach(el => {
    el.innerHTML = `Showing <strong>${Math.min(1 + (currentPage-1)*100, total)}–${Math.min(currentPage*100, total)}</strong> of <strong>${total.toLocaleString()}</strong> assets`;
  });
}

function switchCategory(btn, cat) {
  currentCategory = cat;
  currentPage = 1;
  document.querySelectorAll('#category-tabs .tab-btn').forEach(b => {
    b.classList.remove('active-brand');
    b.classList.remove('active');
  });
  btn.classList.add('active-brand');
  renderTable();
}

function switchNetwork(btn, net) {
  currentNetwork = net;
  currentPage = 1;
  document.querySelectorAll('#network-tabs .net-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  renderTable();
}

function goPage(n) {
  currentPage = n;
  document.querySelectorAll('.page-btn').forEach(b => b.classList.remove('active'));
  document.querySelectorAll('.page-btn').forEach(b => {
    if (b.textContent.trim() == n) b.classList.add('active');
  });
  renderTable();
  document.querySelector('.table-wrapper').scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function sortTable(col) {
  // Visual feedback only — re-sort ALL_COINS
  const thMap = { rank: 0, name: 1, price: 3, '1h': 4, '24h': 5, '7d': 6, mcap: 7, vol: 8 };
  const idx = thMap[col];
  if (idx === undefined) return;

  // Toggle direction
  const ths = document.querySelectorAll('thead th');
  let dir = 1;
  ths.forEach(th => {
    if (th.classList.contains('sorted')) {
      dir = th.dataset.dir == '1' ? -1 : 1;
      th.classList.remove('sorted');
    }
  });

  ALL_COINS.sort((a, b) => {
    const va = a[idx], vb = b[idx];
    if (typeof va === 'string') return dir * va.localeCompare(vb);
    return dir * (va - vb);
  });

  renderTable();
}

function toggleStar(el) {
  el.classList.toggle('active');
  el.textContent = el.classList.contains('active') ? '★' : '☆';
}

function toggleFilters() {
  const p = document.getElementById('filter-panel');
  p.classList.toggle('open');
}

function toggleColumns() {
  const p = document.getElementById('columns-panel');
  p.classList.toggle('open');
}

function toggleCol(colName, checkbox) {
  const label = checkbox.closest('.col-toggle');
  label.classList.toggle('active', checkbox.checked);

  const colClass = {
    '1h': '.col-1h',
    '7d': '.col-7d',
    'supply': '.col-supply',
    'spark': '.col-sparkline, .sparkline-cell',
    'price': '.price-val',
    'mcap': '.mcap-val',
    'vol': '.vol-val',
  };

  if (colClass[colName]) {
    document.querySelectorAll(colClass[colName]).forEach(el => {
      el.style.display = checkbox.checked ? '' : 'none';
    });
  }
}

function toggleSummary() {
